func (p *TransactionProbe) Committed(tb testing.TB) bool {
	tb.Helper()
	if p.id == 0 {
		return false
	}
	exists, err := p.db.NewSelect().TableExpr(`users.guardian_profiles`).Where("id = ?", p.id).Exists(context.Background())
	require.NoError(tb, err)
	return exists
}
